        UUID id = UUID.randomUUID();
        db.update("insert into election (id, label, reference, active, revision, open_items, voting_duration_in_hours) values (?, ?, ?, true, 1, 0, ?)",
            id, caption.strip(), ref, 1);
        return id;
    }
}

